const HIJRI_SETTING_KEY="zad_hijri_offset";function getHijriOffset(){const n=parseInt(localStorage.getItem(HIJRI_SETTING_KEY)||"0",10);return isNaN(n)||n<-3||n>3?0:n}function setHijriOffset(n){const v=Math.max(-3,Math.min(3,parseInt(n,10)||0));localStorage.setItem(HIJRI_SETTING_KEY,String(v));refreshHijriDisplay();return v}window.setHijriOffset=setHijriOffset;window.getHijriOffset=getHijriOffset;function _toLatinDigits(v){return String(v).replace(/[\u0660-\u0669]/g,d=>"٠١٢٣٤٥٦٧٨٩".indexOf(d)).replace(/[\u06F0-\u06F9]/g,d=>"۰۱۲۳۴۵۶۷۸۹".indexOf(d))}window._toLatinDigits=_toLatinDigits;function getHijriDateAccurate(date=new Date){const offset=getHijriOffset();const adjusted=new Date(date);adjusted.setDate(adjusted.getDate()+offset);try{const fmt=new Intl.DateTimeFormat("ar-SA-u-ca-islamic-umalqura-nu-latn",{day:"numeric",month:"numeric",year:"numeric"});const parts=fmt.formatToParts(adjusted);const get=type=>{const n=parseInt(_toLatinDigits(parts.find(p=>p.type===type)?.value||"0"),10);return isNaN(n)?0:n};const h={year:get("year"),month:get("month"),day:get("day"),source:"umalqura"};if(!h.year||!h.month||!h.day)return getHijriDateFallback(adjusted);return h}catch{return getHijriDateFallback(adjusted)}}function getHijriDateFallback(date){const HIJRI_REF={greg:new Date(2026,4,18,0,0,0),year:1447,month:12,day:1};const MONTH_LEN=[30,29,30,29,30,29,30,29,30,29,30,29];const diffDays=Math.round((date-HIJRI_REF.greg)/864e5);let{year:year,month:month,day:day}=HIJRI_REF;let d=day-1+diffDays;if(d>=0){while(d>=MONTH_LEN[month-1]){d-=MONTH_LEN[month-1];month++;if(month>12){month=1;year++}}}else{while(d<0){month--;if(month<1){month=12;year--}d+=MONTH_LEN[month-1]}}return{year:year,month:month,day:d+1,source:"fallback"}}window.getHijriDate=getHijriDateAccurate;const HIJRI_MONTHS=["محرم","صفر","ربيع الأول","ربيع الآخر","جمادى الأولى","جمادى الآخرة","رجب","شعبان","رمضان","شوال","ذو القعدة","ذو الحجة"];function formatHijriDate(date=new Date){const h=getHijriDateAccurate(date);return`${h.day} ${HIJRI_MONTHS[h.month-1]} ${h.year} هـ`}window.formatHijriDate=formatHijriDate;function refreshHijriDisplay(){const str=formatHijriDate();document.querySelectorAll("#hijri-full, .hd-hijri, [data-hijri]").forEach(el=>{el.textContent=str})}window.fetchAndCacheHijriDate=async function(){try{const today=new Date;const key="zad_hijri_today";const todayStr=today.toISOString().split("T")[0];const h=getHijriDateAccurate(today);localStorage.setItem(key,JSON.stringify({y:h.year,m:h.month,d:h.day,greg:todayStr,ts:Date.now(),source:h.source,offset:getHijriOffset()}));document.querySelectorAll("#hijri-full, .hd-hijri").forEach(el=>{el.textContent=`${h.day} ${HIJRI_MONTHS[h.month-1]} ${h.year} هـ`})}catch(e){}};(function loadAdhan(){if(window.adhan)return;const LOCAL="js/vendor/adhan.min.js";const CDN="https://cdn.jsdelivr.net/npm/adhan@4.4.6/lib/bundles/adhan.umd.min.js";const add=(src,onerror)=>{const el=document.createElement("script");el.src=src;el.async=false;if(onerror)el.onerror=onerror;document.head.appendChild(el);return el};add(LOCAL,()=>{add(CDN)})})();const CALC_METHOD_KEY="zad_prayer_method";const CALC_METHODS={Egypt:{name:"الهيئة المصرية للمساحة",key:"Egypt"},UmmAlQura:{name:"أم القرى (السعودية)",key:"UmmAlQura"},MWL:{name:"رابطة العالم الإسلامي",key:"MWL"},ISNA:{name:"أمريكا الشمالية",key:"ISNA"},Karachi:{name:"كراتشي",key:"Karachi"},Kuwait:{name:"الكويت",key:"Kuwait"},Qatar:{name:"قطر",key:"Qatar"},Dubai:{name:"دبي",key:"Dubai"},Turkey:{name:"ديانت — تركيا",key:"Turkey"},Singapore:{name:"سنغافورة",key:"Singapore"},Tehran:{name:"طهران",key:"Tehran"},Moonsighting:{name:"لجنة رؤية الهلال",key:"Moonsighting"}};const ADHAN_KEY={Egypt:"Egyptian",UmmAlQura:"UmmAlQura",MWL:"MuslimWorldLeague",ISNA:"NorthAmerica",Karachi:"Karachi",Kuwait:"Kuwait",Qatar:"Qatar",Dubai:"Dubai",Turkey:"Turkey",Singapore:"Singapore",Tehran:"Tehran",Moonsighting:"MoonsightingCommittee"};const ALADHAN_TO_ADHAN={1:"Karachi",2:"ISNA",3:"MWL",4:"UmmAlQura",5:"Egypt",7:"Tehran",9:"Kuwait",10:"Qatar",11:"Singapore",12:"MWL",13:"Turkey",15:"Moonsighting",16:"Dubai"};const ADHAN_TO_ALADHAN={};Object.entries(ALADHAN_TO_ADHAN).forEach(([id,k])=>{if(!(k in ADHAN_TO_ALADHAN))ADHAN_TO_ALADHAN[k]=Number(id)});const METHOD_ID_KEY="zad_prayer_method_id";function getPrayerMethod(){const id=parseInt(localStorage.getItem(METHOD_ID_KEY)||"",10);if(!isNaN(id)&&ALADHAN_TO_ADHAN[id])return ALADHAN_TO_ADHAN[id];const stored=localStorage.getItem(CALC_METHOD_KEY);return stored&&ADHAN_KEY[stored]?stored:"Egypt"}function setPrayerMethod(method){localStorage.setItem(CALC_METHOD_KEY,method);const id=ADHAN_TO_ALADHAN[method];if(id!==undefined)localStorage.setItem(METHOD_ID_KEY,String(id));return method}const MADHAB_KEY="zad_prayer_madhab";function getMadhab(){return localStorage.getItem(MADHAB_KEY)==="hanafi"?"hanafi":"shafi"}function setMadhab(m){const v=m==="hanafi"?"hanafi":"shafi";localStorage.setItem(MADHAB_KEY,v);return v}window.setPrayerMethod=setPrayerMethod;window.getPrayerMethod=getPrayerMethod;window.CALC_METHODS=CALC_METHODS;window.ADHAN_KEY=ADHAN_KEY;window.getMadhab=getMadhab;window.setMadhab=setMadhab;async function calcPrayerTimes(lat,lng,date=new Date,opts={}){await waitForAdhan();const methodKey=opts.method||getPrayerMethod();const adhanName=ADHAN_KEY[methodKey]||ADHAN_KEY.Egypt;const factory=adhan.CalculationMethod[adhanName]||adhan.CalculationMethod.Egyptian;const params=factory();if(adhan.Madhab&&(opts.madhab||getMadhab())==="hanafi")params.madhab=adhan.Madhab.Hanafi;const coords=new adhan.Coordinates(lat,lng);const times=new adhan.PrayerTimes(coords,date,params);const tz=opts.timezone||undefined;function fmt(t){if(!t)return"--:--";return t.toLocaleTimeString("ar-EG",{hour:"2-digit",minute:"2-digit",hourCycle:"h23",timeZone:tz})}const out={fajr:{time:times.fajr,label:"الفجر",fmt:fmt(times.fajr)},sunrise:{time:times.sunrise,label:"الشروق",fmt:fmt(times.sunrise)},dhuhr:{time:times.dhuhr,label:"الظهر",fmt:fmt(times.dhuhr)},asr:{time:times.asr,label:"العصر",fmt:fmt(times.asr)},maghrib:{time:times.maghrib,label:"المغرب",fmt:fmt(times.maghrib)},isha:{time:times.isha,label:"العشاء",fmt:fmt(times.isha)},method:methodKey};try{if(adhan.SunnahTimes){const st=new adhan.SunnahTimes(times);out.midnight={time:st.middleOfTheNight,label:"منتصف الليل",fmt:fmt(st.middleOfTheNight)};out.lastthird={time:st.lastThirdOfTheNight,label:"الثلث الأخير",fmt:fmt(st.lastThirdOfTheNight)}}}catch(e){}return out}function waitForAdhan(maxWait=5e3){return new Promise((resolve,reject)=>{if(window.adhan){resolve();return}const start=Date.now();const check=setInterval(()=>{if(window.adhan){clearInterval(check);resolve()}else if(Date.now()-start>maxWait){clearInterval(check);reject(new Error("adhan.js timeout"))}},50)})}window.fetchPrayerTimesIfPossible=async function(){try{const pos=await window._getGeoLocation({timeout:8e3});const{latitude:lat,longitude:lng}=pos.coords;const times=await calcPrayerTimes(lat,lng);return times.maghrib.time}catch(e){return null}};window.calcPrayerTimes=calcPrayerTimes;async function renderPrayerTimesPage(){const container=document.getElementById("prayer-times-container");if(!container)return;try{const pos=await window._getGeoLocation({timeout:8e3});const{latitude:lat,longitude:lng}=pos.coords;const times=await calcPrayerTimes(lat,lng);const method=CALC_METHODS[times.method]?.name||times.method;container.innerHTML=`\n      <div class="prayer-method-badge">\n        📍 طريقة الحساب: ${method}\n        <button onclick="showMethodPicker()" class="btn btn-ghost" style="font-size:12px;padding:4px 10px">تغيير</button>\n      </div>\n      ${Object.entries(times).filter(([,p])=>p&&p.time instanceof Date).map(([key,p])=>`\n        <div class="prayer-row ${key}">\n          <span class="prayer-name">${p.label}</span>\n          <span class="prayer-time" data-time24="${p.fmt}">${p.fmt}</span>\n        </div>\n      `).join("")}\n    `;if(typeof applyClockFormat==="function")applyClockFormat()}catch(e){const msg=!window.adhan||e&&e.message==="adhan.js timeout"?"تعذّر تحميل محرك حساب المواقيت — تحقّق من اتصال الإنترنت ثم أعد المحاولة":"تعذّر الحصول على الموقع — فعّل GPS أو اختر مدينتك يدوياً من صفحة المواقيت";container.innerHTML=`<div class="error-state">${msg}</div>`}}window.renderPrayerTimesPage=renderPrayerTimesPage;function showMethodPicker(){const current=getPrayerMethod();const madhab=getMadhab();const modal=document.createElement("div");modal.style.cssText="position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px";modal.innerHTML=`\n    <div style="background:var(--card);border-radius:20px;padding:24px;width:100%;max-width:360px">\n      <h3 style="margin:0 0 16px;font-size:16px;color:var(--ink)">اختر طريقة حساب المواقيت</h3>\n      ${Object.entries(CALC_METHODS).map(([key,m])=>`\n        <div onclick="setPrayerMethod('${key}');document.body.removeChild(this.closest('[style*=fixed]'));if(typeof showToast==='function')showToast('✅ تم اختيار: ${m.name}');setTimeout(()=>location.reload(),800)"\n          style="padding:14px 16px;border-radius:12px;cursor:pointer;margin-bottom:8px;\n                 background:${key===current?"rgba(14,59,46,.1)":"var(--sand)"};\n                 border:${key===current?"2px solid var(--green-deep)":"1.5px solid var(--border)"}">\n          <div style="font-size:14px;font-weight:${key===current?800:500}">${m.name} ${key===current?"✓":""}</div>\n        </div>\n      `).join("")}\n      <div style="margin-top:16px;padding-top:14px;border-top:1.5px solid var(--border)">\n        <h3 style="margin:0 0 10px;font-size:14px;color:var(--ink)">مذهب حساب العصر</h3>\n        <div style="display:flex;gap:8px">\n          ${[["shafi","الجمهور"],["hanafi","حنفي"]].map(([k,label])=>`\n            <div data-madhab="${k}" onclick="setMadhab('${k}');this.parentElement.querySelectorAll('[data-madhab]').forEach(e=>{e.style.background='var(--sand)';e.style.borderColor='var(--border)';e.firstElementChild.style.fontWeight='500'});this.style.background='rgba(14,59,46,.1)';this.style.borderColor='var(--green-deep)';this.firstElementChild.style.fontWeight='800';if(typeof showToast==='function')showToast('✅ مذهب: ${label}')"\n              style="flex:1;padding:10px 12px;border-radius:12px;cursor:pointer;text-align:center;\n                     background:${k===madhab?"rgba(14,59,46,.1)":"var(--sand)"};\n                     border:${k===madhab?"2px solid var(--green-deep)":"1.5px solid var(--border)"}">\n              <b style="font-size:13px;font-weight:${k===madhab?800:500}">${label} ${k===madhab?"✓":""}</b>\n            </div>`).join("")}\n        </div>\n        <div style="margin-top:8px;font-size:12px;color:var(--muted);line-height:1.6">\n          الحنفي يؤخّر العصر حتى يصير الظل مثليّ القامة (نحو 45 دقيقة بعد الجمهور). لا يؤثر في بقية الصلوات.\n        </div>\n      </div>\n      <button onclick="document.body.removeChild(this.closest('[style*=fixed]'))" \n        style="width:100%;padding:12px;border:none;background:none;color:var(--muted);font-family:inherit;cursor:pointer;margin-top:8px">\n        إلغاء\n      </button>\n    </div>`;document.body.appendChild(modal)}window.showMethodPicker=showMethodPicker;function injectHijriOffsetControl(){const container=document.getElementById("hijri-offset-container");if(!container)return;const current=getHijriOffset();container.innerHTML=`\n    <div class="setting-row">\n      <div class="setting-label">\n        <div style="font-weight:700;margin-bottom:4px">ضبط التاريخ الهجري</div>\n        <div style="font-size:12px;color:var(--muted)">\n          في حال اختلاف التاريخ مع إعلان رؤية الهلال، يمكنك ضبطه يدوياً\n        </div>\n      </div>\n      <div style="display:flex;align-items:center;gap:10px;margin-top:10px">\n        <button onclick="setHijriOffset(getHijriOffset()-1)" class="btn btn-ghost" style="padding:8px 14px">-1</button>\n        <span id="hijri-offset-display" style="font-size:14px;font-weight:700;min-width:40px;text-align:center">\n          ${current>0?"+":""}${current}\n        </span>\n        <button onclick="setHijriOffset(getHijriOffset()+1)" class="btn btn-ghost" style="padding:8px 14px">+1</button>\n        <button onclick="setHijriOffset(0)" class="btn btn-ghost" style="padding:8px 14px;font-size:12px">إعادة</button>\n      </div>\n      <div style="margin-top:8px;font-size:13px;color:var(--muted)">\n        التاريخ الحالي: <strong id="hijri-current-display">${formatHijriDate()}</strong>\n      </div>\n    </div>\n  `}const _origSetOffset=window.setHijriOffset;window.setHijriOffset=function(n){const v=_origSetOffset(n);const display=document.getElementById("hijri-offset-display");if(display)display.textContent=v>0?`+${v}`:String(v);const current=document.getElementById("hijri-current-display");if(current)current.textContent=formatHijriDate()};document.addEventListener("DOMContentLoaded",()=>{refreshHijriDisplay();injectHijriOffsetControl()});